import Foundation

/// App identity and the build stamp.
///
/// The user asked for a way to tell, after every edit, what version is running.
/// The stamp is a hash of the source tree, so a rebuild with any edit at all
/// carries a different one and there is never doubt about what is running.
///
/// `BuildStamp` is generated by `build.sh` into `build/gen/BuildStamp.swift` on
/// every compile, so it always reflects the source tree that was actually built.
/// The values below are only the fallback for running the binary without it.
enum AppVersion {
    /// Marketing version, shown in the sidebar footer and the About card.
    static let marketing = Bundle.main.infoDictionary?["CFBundleShortVersionString"] as? String
        ?? BuildStamp.marketing
    /// Build number, incremented by build.sh whenever the source tree changed.
    static var build: String { BuildStamp.build }
    /// Short source hash, so two builds of the same version are distinguishable.
    static var sourceHash: String { BuildStamp.hash }
    /// When this binary was compiled.
    static var builtAt: String { BuildStamp.date }
    /// One line for the sidebar footer and the About card.
    static var line: String { "\(marketing) · build \(build) · \(sourceHash)" }

    /// The release history, newest first, and the only source of both the
    /// version's description and the version number's justification.
    ///
    /// Written by hand when a release is cut, not appended to by the build script.
    /// That distinction matters: for a while every compile invented a new version
    /// while the notes stayed where they were, so the app showed "1.10" above a
    /// list that ended at 1.7. A version without an entry here cannot be built —
    /// `build.sh` checks — and the running version is never inferred from a counter.
    static let history: [(version: String, notes: [String])] = [
        ("2.4", [
            "Pictures load six at a time instead of one after another. A screen of nine cards used to queue nine downloads end to end, each with a fifteen-second timeout and a retry, so the last card could wait two minutes while the grid looked broken. A screenful now arrives in about two and a half seconds, measured by a new command that times the app's own loader rather than a download script.",
            "A picture that is already on disk is decoded off the main thread. Reading it on the main thread was the stutter when scrolling.",
            "The picture extractor was reading the wrong attribute. It took the first quoted string in the tag, which is the width, so every feed that wrote its attributes in the usual order produced no picture at all.",
            "A publisher's mark is no longer judged by its file name. On a logo-design blog the word \"logo\" in a name is the subject of the story, not the site's logo, and 350 real pictures were being thrown away for that reason. The size the page declares now decides, with the name only breaking a tie.",
            "A picture the site marks as 60 by 60 is an avatar, not a cover, and is treated as one.",
            "A picture the publisher rate-limited is tried again after a pause instead of being left blank for good.",
            "Pictures are stored at the size they are drawn, so the cache is about forty times smaller: 24 pictures take 4 MB where they took 160 MB, and the cache now has a ceiling.",
            "A story that was stored without a picture is read again from the cached feed, so a fix to the extractor also reaches the stories already in the archive.",
            "Sidebar.io removed (feed returns 200 but zero items); Google Fonts moved to unavailable (feed stopped June 2024, no live font-news feed on publisher site); WordPress JSON date parsing fixed (dates without zone like 2026-10-22T02:55:04 now read via date_gmt); Shopify listing date lookup now also searches the short link form (/news/slug) printed on the page."
        ]),
        ("2.3", [
            "Fourteen publishers added to the design tab, across five parts of the beat it was missing: branding, logos, packaging, typography and advertising.",
            "Every feed was fetched and read before being listed: BP&O, Brandingmag, Logo Geek, Logo Design Love, The Dieline, Packaging of the World, Packaging News, Fontfabric, Communication Arts, Campaign Brief, Marketing Dive, Abduzeedo and designboom. Brand New's only feed is its podcast, so its blog is read from its archive instead.",
            "Five sections are new — Branding & Visual Identity, Logo Design & Rebranding, Packaging Design, Typography & Fonts, Advertising & Creative Campaigns — because the old eight had nowhere to put a packaging story.",
            "Fonts and Design Resources was split: type now has its own section, and the resource section keeps the stock libraries and asset shops.",
            "A slow publisher keeps its newest stories. The retention window was written for the news firehose; applied to a blog that posts twice a month it erased the only story there was, and the section read as broken while the source reported success.",
            "Ten of the requested publishers are named as unavailable rather than added as sources that would show nothing: Creative Review, Design Week, World Brand Design, Lovely Package, Adobe Fonts, MyFonts and Eye Magazine; Identity Designed because its feed stopped in December 2024; Adobe's two release-note pages, which are help articles that change in place and carry no story to date; and OpenAI News, already read by AI News, where adding it would store every story twice.",
            "Nothing was recreated: the tab, its filters, its chips and its cards are the ones that were already there."
        ]),
        ("2.2", [
            "The news tab is now AI News, named for what it actually reads: the models and research sources, not the whole beat.",
            "Opening the app a second time brings the window already running to the front instead of starting another copy. Every copy was loading the whole archive and its own pictures into memory, so a few launches could take a Mac to its knees.",
            "Pictures are decoded at the size they are drawn and charged what they really occupy, so the memory ceiling is real. Before, a cover photo was charged a tenth of what it used, the limit never fired, and a single screen of cards could hold a gigabyte.",
            "A feed with a bare \"&\" in a link no longer reads as empty. Motionographer lost every story that way while reporting success.",
            "A sources file carrying the same entry twice no longer crashes the app on launch.",
            "The environment report names the folder the app really uses."
        ]),
        ("2.1", [
            "A new tab, Design & Web Intelligence, for the part of this beat that never fit the AI list: design, the web platform, search, analytics and 3D.",
            "Thirty-nine feeds behind it, every one fetched and checked before being added. Eight sections, each with a chip that counts what it would show.",
            "Twenty-two publishers from the requested list serve no feed at all and are named as unavailable instead of being faked into the list.",
            "The tab keeps its own window, defaulting to everything stored. A design blog posts twice a month, so a twelve-hour default would open it half empty.",
            "Its results are counted apart from the news, so \"News 507\" no longer silently includes a hundred font releases.",
            "Wix dated one post two months into the future, which would have pinned it to the top of every list until December. A feed date beyond an hour ahead is now treated as now."
        ]),
        ("2.0", [
            "The version is a release, not a counter: 1.9 is followed by 2.0, and the number only moves when a release is cut.",
            "Each release ships with its notes: the build refuses to produce a version that has none.",
            "The toolbar is a band again, so no story can ever appear above it.",
            "Stories dissolve into the top edge instead of being sheared off at a line.",
            "The briefing is a summary plus a ranked list, not a page of numbers and prose that repeat each other.",
            "The source list in the sidebar wraps its counts instead of letting \"1,308\" push the name out of view.",
            "Source Status shows what each source has stored, window by window, and stops calling the feed's entry count \"items\".",
            "Filtering to one publisher no longer lands on an empty page: the app says which window does have stories, and offers it in one click.",
            "TechCrunch, Ars Technica and MIT Technology Review are read three pages back, because each publishes twenty entries per page."
        ]),
        ("1.9", [
            "Content scrolls under the toolbar and fades out there, rather than stopping at a hard line.",
            "The sidebar, toolbar and page share one neutral surface; the wine accent marks selection and actions only.",
            "Panel edges and dividers are hairlines that stay visible in dark mode."
        ]),
        ("1.8", [
            "A project's detail sheet shows its whole README as the original text.",
            "The reader keeps inline pictures and links, in page order.",
            "Cards say \"Read here\" only when the article can really be read in the app."
        ]),
        ("1.7", [
            "The reader drops the byline headshot, sign-up lines and duplicate lead pictures.",
            "Every source failure is explained in words; transient failures are retried once."
        ]),
        ("1.6", [
            "9router can write the summaries, next to Ollama.",
            "The source list sits in a fixed box in the sidebar instead of filling it.",
            "The window has its standard close, minimise and full-screen buttons again."
        ]),
        ("1.5", [
            "Eighteen new sources, twenty-four in total.",
            "News and GitHub split into separate sections.",
            "Time filters: 12h, 24h, 72h and one week."
        ]),
        ("1.0", [
            "First build: seven sources, offline digest, GitHub trending."
        ])
    ]

    /// What this build changed — the entry for the version that is actually
    /// running, so the notes and the number can never disagree.
    static var releaseNotes: [String] {
        history.first { $0.version == marketing }?.notes
            ?? ["This build has no notes filed under \(marketing). That is a bug in the build, not a claim about the release."]
    }

    /// The full list, as shown in Settings.
    static var changelog: [(String, [String])] {
        history.map { ($0.version, $0.notes) }
    }
}
